3047	// 本机请求重放与响应差异报告（replay 子命令）
3048	// ---------------------------------------------------------------------------
3049	//
3050	// 读取 GET /__contractlab/requests 的完整 JSON 快照，按输入顺序保留原编号，
3051	// 把每条记录的原始请求逐条重放到 127.0.0.1 的指定端口：前一条结束才发下一条，
3052	// 每次执行每条只尝试一次，不跟随重定向。仅比较实际响应的状态码与正文原始字节
3053	// 和记录中的计划响应（计划正文按 UTF-8 编码）；不比较响应头，也不依据记录版本
3054	// 与发送状态判定——pending / sent / interrupted 均可重放，400/404/500 同样按
3055	// 内容比较。不监听端口、不修改文件；已发送的请求可能已被目标处理，不重载、
3056	// 清空或回滚目标状态。
3057	//
3058	// 仅重放 GET/POST；target 须为以 "/" 开头的合法 HTTP 请求目标，原样发送
3059	// （保留查询串与百分号编码，不归一化路径）；禁止重放 /__contractlab 本身及
3060	// /__contractlab/ 前缀路径。每条记录另须有 200–599 的计划响应状态与文本正文。
3061	// 参数与全部记录（含可发送的头名称和值）有效后才连接；参数或快照失败退出 2，
3062	// stderr 给原因，stdout 为空且不发任何请求。
3063	//
3064	// 每条请求的总超时自开始连接覆盖完整收发，持续来数据也不延长；连接失败、
3065	// 超时或响应中途断开记通信失败，关闭连接后继续下一条（部分响应不算完整）。
3066	
3067	// 重放时剥离的头（小写）：原 Host / Expect / HTTP 逐跳与分帧头；
3068	// Connection 头指名的头名也一并剥离。Host 与 Content-Length 按目标和实际
3069	// 字节数重建。
3070	const REPLAY_STRIP_HEADERS: ReadonlySet<string> = new Set([
3071	  'host',
3072	  'expect',
3073	  'connection',
3074	  'keep-alive',
3075	  'content-length',
3076	  'transfer-encoding',
3077	  'te',
3078	  'trailer',
3079	  'upgrade',
3080	  'proxy-authenticate',
3081	  'proxy-authorization',
3082	]);
3083	
3084	// 一条待重放的请求：共享快照校验之上再经重放专用校验
3085	interface ReplayRequest {
3086	  readonly id: number;
3087	  readonly method: 'GET' | 'POST';
3088	  // 原样发送的请求目标（含查询串与百分号编码，不归一化）
3089	  readonly target: string;
3090	  // 过滤后的业务头：名称大小写、重复项与在线顺序原样保留
3091	  readonly headers: readonly [string, string][];
3092	  readonly body: Buffer;
3093	  readonly plannedStatus: number;
3094	  readonly plannedBody: string;
3095	}
3096	
3097	// target 须为以 "/" 开头的合法 HTTP 请求目标：不含空白与控制字符，
3098	// 且每个字符都在 Latin-1 内（与 Node 客户端对 path 的接受范围一致）
3099	function validateReplayTarget(target: string, where: string): void {
3100	  if (target.length === 0 || !target.startsWith('/')) {
3101	    snapshotFail(where, `必须是以 "/" 开头的 HTTP 请求目标，收到 ${JSON.stringify(target)}`);
3102	  }
3103	  for (const ch of target) {
3104	    const code = ch.charCodeAt(0);
3105	    if (code <= 0x20 || code === 0x7f) {
3106	      snapshotFail(where, `含空白或控制字符，不是合法的 HTTP 请求目标：${JSON.stringify(target)}`);
3107	    }
3108	    if (code > 0xff) {
3109	      snapshotFail(where, `含 Latin-1 之外的字符，无法作为 HTTP 请求目标发送：${JSON.stringify(target)}`);
3110	    }
3111	  }
3112	}
3113	
3114	// 过滤并校验待发送的业务头：剥离 Host/Expect/逐跳/分帧头（含 Connection
3115	// 指名的头），其余按原顺序、大小写与重复项保留；保留的头名称与值必须可发送。
3116	function filterReplayHeaders(
3117	  rawHeaders: readonly string[],
3118	  where: string,
3119	): [string, string][] {
3120	  const connectionNamed = new Set<string>();
3121	  for (let j = 0; j + 1 < rawHeaders.length; j += 2) {
3122	    if ((rawHeaders[j] as string).toLowerCase() === 'connection') {
3123	      for (const token of (rawHeaders[j + 1] as string).split(',')) {
3124	        const name = token.trim().toLowerCase();
3125	        if (name !== '') {
3126	          connectionNamed.add(name);
3127	        }
3128	      }
3129	    }
3130	  }
3131	  const out: [string, string][] = [];
3132	  for (let j = 0; j + 1 < rawHeaders.length; j += 2) {
3133	    const name = rawHeaders[j] as string;
3134	    const value = rawHeaders[j + 1] as string;
3135	    const lower = name.toLowerCase();
3136	    if (REPLAY_STRIP_HEADERS.has(lower) || connectionNamed.has(lower)) {
3137	      continue;
3138	    }
3139	    if (!HEADER_NAME_RE.test(name)) {
3140	      snapshotFail(`${where}[${j}]`, `不是可发送的 HTTP 头名称：${JSON.stringify(name)}`);
3141	    }
3142	    for (let k = 0; k < value.length; k += 1) {
3143	      const code = value.charCodeAt(k);
3144	      // 与响应头同一规则：允许水平制表符；拒绝换行及其余控制字符；仅 Latin-1
3145	      if ((code <= 0x1f && code !== 0x09) || code === 0x7f || code > 0xff) {
3146	        snapshotFail(
3147	          `${where}[${j + 1}]`,
3148	          `头 ${JSON.stringify(name)} 的值不得包含换行或其他控制字符，且只能使用 Latin-1 字符`,
3149	        );
3150	      }
3151	    }
3152	    out.push([name, value]);
3153	  }
3154	  return out;
3155	}
3156	
3157	function parseReplayRecord(raw: unknown, index: number, seen: Set<number>): ReplayRequest {
3158	  const where = `records[${index}]`;
3159	  // 先完整经历与 verify 相同的快照校验（含 target/path 一致性与正文无损性）
3160	  const base = parseSnapshotRecord(raw, index, seen);
3161	
3162	  if (base.method !== 'GET' && base.method !== 'POST') {
3163	    snapshotFail(
3164	      `${where}.request.method`,
3165	      `仅支持重放 GET/POST，收到 ${JSON.stringify(base.method)}`,
3166	    );
3167	  }
3168	  validateReplayTarget(base.target, `${where}.request.target`);
3169	  if (base.path === ADMIN_BASE || base.path.startsWith(ADMIN_PREFIX)) {
3170	    snapshotFail(
3171	      `${where}.request.target`,
3172	      `指向管理入口（${ADMIN_BASE} 本身及 ${ADMIN_PREFIX} 前缀），禁止重放`,
3173	    );
3174	  }
3175	
3176	  // 每条记录另须有 200–599 的计划响应状态与文本正文（比较基准）
3177	  const prWhere = `${where}.plannedResponse`;
3178	  const planned = (raw as Record<string, unknown>).plannedResponse;
3179	  if (!isPlainObject(planned)) {
3180	    snapshotFail(prWhere, '必须是对象（重放需要计划响应状态与文本正文）');
3181	  }
3182	  const { status, body } = planned;
3183	  if (!Number.isInteger(status) || (status as number) < 200 || (status as number) > 599) {
3184	    snapshotFail(
3185	      `${prWhere}.status`,
3186	      `必须是 200 至 599 之间的整数，收到 ${JSON.stringify(status)}`,
3187	    );
3188	  }
3189	  if (typeof body !== 'string') {
3190	    snapshotFail(`${prWhere}.body`, '必须是文本字符串');
3191	  }
3192	  if (hasLoneSurrogate(body as string)) {
3193	    snapshotFail(
3194	      `${prWhere}.body`,
3195	      '含孤立代理项（lone surrogate）：按 UTF-8 编码会被替换字符改写，无法作为无损的比较基准',
3196	    );
3197	  }
3198	
3199	  return {
3200	    id: base.id,
3201	    method: base.method,
3202	    target: base.target,
3203	    headers: filterReplayHeaders(base.rawHeaders, `${where}.request.rawHeaders`),
3204	    body: base.body,
3205	    plannedStatus: status as number,
3206	    plannedBody: body as string,
3207	  };
3208	}
3209	
3210	function parseReplaySnapshot(raw: unknown): ReplayRequest[] {
3211	  const seen = new Set<number>();
3212	  return snapshotRecordsOf(raw).map((rec, i) => parseReplayRecord(rec, i, seen));
3213	}
3214	
3215	// 读取 -> 解析 -> 校验并重建；任何一步失败都抛出含文件路径与可定位原因的错误
3216	async function loadReplaySnapshotFromFile(snapshotPath: string): Promise<ReplayRequest[]> {
3217	  let text: string;
3218	  try {
3219	    text = await readFile(snapshotPath, 'utf8');
3220	  } catch (e) {
3221	    throw new Error(`读取请求记录快照文件 ${snapshotPath} 失败：${describeError(e)}`);
3222	  }
3223	
3224	  let raw: unknown;
3225	  try {
3226	    raw = JSON.parse(text);
3227	  } catch (e) {
3228	    throw new Error(`请求记录快照文件 ${snapshotPath} 不是合法 JSON：${describeError(e)}`);
3229	  }
3230	
3231	  try {
3232	    return parseReplaySnapshot(raw);
3233	  } catch (e) {
3234	    throw new Error(`请求记录快照文件 ${snapshotPath} 校验失败：${describeError(e)}`);
3235	  }
3236	}
3237	
3238	interface ReplayResponse {
3239	  readonly status: number;
3240	  readonly body: Buffer;
3241	}
3242	
3243	type ReplayExchange =
3244	  | { readonly ok: true; readonly response: ReplayResponse }
3245	  | { readonly ok: false; readonly reason: string };
3246	
3247	// 重放单条请求：独立连接、只尝试一次、不跟随重定向；总超时自开始连接覆盖
3248	// 完整收发，不因持续来数据而延长。通信失败时关闭连接并返回原因。
3249	function replayOne(port: number, request: ReplayRequest, timeoutMs: number): Promise<ReplayExchange> {
3250	  return new Promise((resolve) => {
3251	    let settled = false;
3252	    const done = (outcome: ReplayExchange): void => {
3253	      if (!settled) {
3254	        settled = true;
3255	        clearTimeout(timer);
3256	        resolve(outcome);
3257	      }
3258	    };
3259	
3260	    // 业务头在前（原顺序/大小写/重复项），随后按目标与实际字节数重建
3261	    // Host 与 Content-Length；每条请求独立连接，响应结束后关闭。
3262	    const headers: string[] = [];
3263	    for (const [name, value] of request.headers) {
3264	      headers.push(name, value);
3265	    }
3266	    headers.push('Host', `127.0.0.1:${port}`);
3267	    headers.push('Content-Length', String(request.body.byteLength));
3268	    headers.push('Connection', 'close');
3269	
3270	    const req = http.request({
3271	      host: '127.0.0.1',
3272	      port,
3273	      method: request.method,
3274	      path: request.target, // 原样发送：保留查询串与百分号编码，不归一化
3275	      headers,
3276	      agent: false, // 不连接池化：一次一条，每条只尝试一次
3277	    });
3278	
3279	    // 总超时：覆盖连接建立与完整收发，持续来数据不延长
3280	    const timer = setTimeout(() => {
3281	      req.destroy();
3282	      done({ ok: false, reason: `超过总超时 ${timeoutMs}ms（自开始连接覆盖完整收发）` });
3283	    }, timeoutMs);
3284	
3285	    req.on('response', (res) => {
3286	      const chunks: Buffer[] = [];
3287	      res.on('data', (chunk: Buffer) => chunks.push(chunk));
3288	      res.on('end', () => {
3289	        done({
3290	          ok: true,
3291	          response: { status: res.statusCode ?? 0, body: Buffer.concat(chunks) },
3292	        });
3293	      });
3294	      res.on('aborted', () => {
3295	        done({ ok: false, reason: '响应中途断开（部分响应不算完整）' });
3296	      });
3297	      res.on('error', (e: unknown) => {
3298	        done({ ok: false, reason: `响应读取失败：${describeError(e)}` });
3299	      });
3300	      res.on('close', () => {
3301	        if (!res.complete) {
3302	          done({ ok: false, reason: '响应中途断开（部分响应不算完整）' });
3303	        }
3304	      });
3305	    });
3306	    req.on('error', (e: Error) => {
3307	      done({ ok: false, reason: `通信失败：${e.message}` });
3308	    });
3309	    req.end(request.body);
3310	  });
3311	}
3312	
3313	// 完整响应的无损 JSON 表示（与请求记录正文同一套编码规则）
3314	function replayResponseJson(response: ReplayResponse): {
3315	  status: number;
3316	  body: { encoding: 'utf-8' | 'base64'; content: string };
3317	} {
3318	  return { status: response.status, body: encodeBodyLosslessly(response.body) };
3319	}
3320	
3321	type ReplayResultEntry =
3322	  | {
3323	      readonly id: number;
3324	      readonly outcome: 'same';
3325	      readonly response: ReturnType<typeof replayResponseJson>;
3326	    }
3327	  | {
3328	      readonly id: number;
3329	      readonly outcome: 'different';
3330	      // 差异点：状态码不同 / 正文原始字节不同（可同时为真）
3331	      readonly differences: { readonly status: boolean; readonly body: boolean };
3332	      readonly planned: ReturnType<typeof replayResponseJson>;
3333	      readonly response: ReturnType<typeof replayResponseJson>;
3334	    }
3335	  | { readonly id: number; readonly outcome: 'failed'; readonly reason: string };
3336	
3337	interface ReplayReport {
3338	  readonly requestsFile: string;
3339	  readonly port: number;
3340	  readonly timeoutMs: number;
3341	  readonly total: number;
3342	  readonly same: number;
3343	  readonly different: number;
3344	  readonly failed: number;
3345	  readonly results: readonly ReplayResultEntry[];
3346	}
3347	
3348	async function runReplay(requestsArg: string, port: number, timeoutMs: number): Promise<never> {
3349	  const requestsFile = path.resolve(requestsArg);
3350	
3351	  // 参数与全部记录有效后才连接：任何快照错误都不发任何请求
3352	  let requests: ReplayRequest[];
3353	  try {
3354	    requests = await loadReplaySnapshotFromFile(requestsFile);
3355	  } catch (e) {
3356	    process.stderr.write(`${APP_NAME}: replay 请求快照：${describeError(e)}\n`);
3357	    process.exit(2);
3358	  }
3359	
3360	  // 按输入顺序保留原编号逐条重放：前一条结束才发下一条
3361	  const results: ReplayResultEntry[] = [];
3362	  for (const request of requests) {
3363	    const exchange = await replayOne(port, request, timeoutMs);
3364	    if (!exchange.ok) {
3365	      results.push({ id: request.id, outcome: 'failed', reason: exchange.reason });
3366	      continue;
3367	    }
3368	    const { response } = exchange;
3369	    // 仅比较状态码与正文原始字节；计划正文按 UTF-8 编码
3370	    const statusDiff = response.status !== request.plannedStatus;
3371	    const bodyDiff = !response.body.equals(Buffer.from(request.plannedBody, 'utf8'));
3372	    if (!statusDiff && !bodyDiff) {
3373	      results.push({ id: request.id, outcome: 'same', response: replayResponseJson(response) });
3374	    } else {
3375	      results.push({
3376	        id: request.id,
3377	        outcome: 'different',
3378	        differences: { status: statusDiff, body: bodyDiff },
3379	        planned: {
3380	          status: request.plannedStatus,
3381	          body: { encoding: 'utf-8', content: request.plannedBody },
3382	        },
3383	        response: replayResponseJson(response),
3384	      });
3385	    }
3386	  }
3387	
3388	  const same = results.filter((r) => r.outcome === 'same').length;
3389	  const different = results.filter((r) => r.outcome === 'different').length;
3390	  const failed = results.filter((r) => r.outcome === 'failed').length;
3391	  const report: ReplayReport = {
3392	    requestsFile,
3393	    port,
3394	    timeoutMs,
3395	    total: results.length,
3396	    same,
3397	    different,
3398	    failed,
3399	    results,
3400	  };
3401	  process.stdout.write(`${JSON.stringify(report, null, 2)}\n`);
3402	  // 空快照或全部相同退出 0；存在差异或通信失败退出 1
3403	  process.exit(different === 0 && failed === 0 ? 0 : 1);
3404	}
3405	
3406	// ---------------------------------------------------------------------------
3407	// HTTP 服务
3408	// ---------------------------------------------------------------------------
3409	
3410	// 模块级运行时句柄（启动后赋值）
3411	let activeState: LiveState;
3412	let server: http.Server;
3413	let configFile = '';
3414	let shuttingDown = false;
