126	function httpGetBody(port: number, path: string): Promise<string> {
127	  return new Promise((resolve, reject) => {
128	    const r = http.get({ host: '127.0.0.1', port, path }, (res) => {
129	      let data = '';
130	      res.setEncoding('utf8');
131	      res.on('data', (d: string) => (data += d));
132	      res.on('end', () => resolve(data));
133	    });
134	    r.on('error', reject);
135	    r.setTimeout(10_000, () => r.destroy(new Error(`GET ${path} 超时`)));
136	  });
137	}
