170	function makeRecord(
171	  id: number,
172	  patch?: {
173	    method?: string;
174	    target?: string;
175	    path?: string;
176	    rawHeaders?: string[];
177	    bodyBytes?: number;
178	    body?: { encoding: string; content: string };
179	    plannedResponse?: unknown;
180	  },
181	): Record<string, unknown> {
182	  const target = patch?.target ?? '/api/echo';
183	  const body = patch?.body ?? { encoding: 'utf-8', content: '' };
184	  return {
185	    id,
186	    receivedAt: '2026-10-06T00:00:00.000Z',
187	    request: {
188	      method: patch?.method ?? 'GET',
189	      target,
190	      path: patch?.path ?? target.split('?')[0],
191	      rawHeaders: patch?.rawHeaders ?? ['Host', '127.0.0.1:9999'],
192	      bodyBytes: patch?.bodyBytes ?? 0,
193	      body,
194	    },
195	    configVersion: 1,
196	    matched: true,
197	    endpoint: null,
198	    bodyValidationPassed: null,
199	    bodyRejection: null,
200	    sequencePosition: null,
201	    sequenceLength: null,
202	    plannedResponse: patch?.plannedResponse ?? { kind: 'scene', status: 200, headers: {}, body: 'ok' },
203	    delivery: 'sent',
204	  };
205	}
