211	// 取一个当前空闲的端口（打开后立即关闭，之后无人监听）
212	async function freePort(): Promise<number> {
213	  const server = net.createServer();
214	  await new Promise<void>((resolve) => server.listen(0, '127.0.0.1', resolve));
215	  const address = server.address();
216	  const port = typeof address === 'object' && address ? address.port : 0;
217	  await new Promise<void>((resolve) => server.close(() => resolve()));
218	  return port;
219	}
