19	// ---------------------------------------------------------------------------
20	// 子进程：运行 CLI（compare 等），带有限超时——卡住必须在有限时间内失败
21	// ---------------------------------------------------------------------------
22	
23	export interface CliResult {
24	  readonly code: number;
25	  readonly stdout: string;
26	  readonly stderr: string;
27	}
28	
29	export async function runCli(args: readonly string[], timeoutMs = 20_000): Promise<CliResult> {
30	  const child = spawn(process.execPath, [APP_PATH, ...args], {
31	    stdio: ['ignore', 'pipe', 'pipe'],
32	  });
33	  let stdout = '';
34	  let stderr = '';
35	  child.stdout.setEncoding('utf8').on('data', (d: string) => (stdout += d));
36	  child.stderr.setEncoding('utf8').on('data', (d: string) => (stderr += d));
37	
38	  let timedOut = false;
39	  const timer = setTimeout(() => {
40	    timedOut = true;
41	    child.kill('SIGKILL');
42	  }, timeoutMs);
43	  const [code, signal] = (await once(child, 'exit')) as [number | null, string | null];
44	  clearTimeout(timer);
45	
46	  if (timedOut) {
47	    throw new Error(
48	      `命令超过 ${timeoutMs}ms 未结束（疑似卡住），已强制终止：node app.ts ${args.join(' ')}`,
49	    );
50	  }
51	  if (code === null) {
52	    throw new Error(
53	      `子进程异常终止（信号 ${signal}）：node app.ts ${args.join(' ')}\nstderr:\n${stderr}`,
54	    );
55	  }
56	  return { code, stdout, stderr };
57	}
