197	class ConfigError extends Error {
198	  constructor(message: string) {
199	    super(message);
200	    this.name = 'ConfigError';
201	  }
202	}
203	
204	// ---------------------------------------------------------------------------
205	// 配置校验
206	// ---------------------------------------------------------------------------
207	
208	function isPlainObject(value: unknown): value is Record<string, unknown> {
209	  return typeof value === 'object' && value !== null && !Array.isArray(value);
210	}
211	
212	function validatePath(p: string, where: string): void {
213	  if (p.length === 0 || p[0] !== '/') {
214	    throw new ConfigError(`${where}.path 必须是以 "/" 开头的绝对路径，收到 "${p}"`);
215	  }
216	  if (p.length > 4096) {
217	    throw new ConfigError(`${where}.path 过长（最多 4096 字符）`);
218	  }
219	  for (const ch of p) {
220	    const code = ch.charCodeAt(0);
221	    if (ch === '?' || ch === '#' || ch === '{' || ch === '}') {
222	      throw new ConfigError(
223	        `${where}.path "${p}" 含有非法字符 "${ch}"：查询串不参与匹配，且不支持路径模板`,
224	      );
225	    }
226	    if (code <= 0x1f || code === 0x7f || code === 0x20) {
227	      throw new ConfigError(`${where}.path "${p}" 不得包含空白或控制字符`);
228	    }
229	  }
230	}
231	
232	function validateResponse(raw: unknown, where: string): ResponseSpec {
233	  if (!isPlainObject(raw)) {
234	    throw new ConfigError(`${where} 必须是对象`);
235	  }
236	  for (const key of Object.keys(raw)) {
237	    if (key !== 'status' && key !== 'headers' && key !== 'body' && key !== 'delay') {
238	      throw new ConfigError(`${where} 含未知字段 "${key}"`);
239	    }
240	  }
241	
242	  const { status, headers, body, delay } = raw;
243	
244	  if (!Number.isInteger(status) || status < 200 || status > 599) {
245	    throw new ConfigError(`${where}.status 必须是 200 至 599 之间的整数，收到 ${JSON.stringify(status)}`);
246	  }
247	
248	  if (!isPlainObject(headers)) {
249	    throw new ConfigError(`${where}.headers 必须是字符串键值对象`);
250	  }
251	  // 无原型对象：名为 "__proto__" 的头也按自有字段保留，不被原型 setter 吞掉
252	  const cleanHeaders: { [name: string]: string } = Object.create(null);
253	  const seenNames = new Set<string>();
254	  for (const [name, value] of Object.entries(headers)) {
255	    const whereHeader = `${where}.headers["${name}"]`;
256	    if (!HEADER_NAME_RE.test(name)) {
