parseStrategyPointer:

```ts
function parseStrategyPointer(raw: unknown, where: string): string {
  if (typeof raw !== 'string') {
    strategyFail(where, `必须是 RFC 6901 指针字符串，收到 ${JSON.stringify(raw)}`);
  }
  if (raw === '') {
    return '';
  }
  if (!raw.startsWith('/')) {
    strategyFail(where, `的指针 ${JSON.stringify(raw)} 非法：非根指针必须以 "/" 开头（根指针为 ""）`);
  }
  for (const [i, segment] of raw.slice(1).split('/').entries()) {
    for (let j = 0; j < segment.length; j += 1) {
      if (segment[j] === '~') {
        const next = segment[j + 1];
        if (next !== '0' && next !== '1') {
          strategyFail(where, `的指针 ${JSON.stringify(raw)} 非法：第 ${i} 段含非法转义（仅支持 ~0 与 ~1）`);
        }
        j += 1;
      }
    }
  }
  return raw;
}
```

