Planned body JSON parse:

```ts
// JSON 语义比较的正文解析：仅可剥离单个开头 BOM；空正文非法。
function parseJsonBodyText(text: string): { ok: true; value: unknown } | { ok: false; reason: string } {
  const stripped = text.startsWith('\uFEFF') ? text.slice(1) : text;
  if (stripped === '') {
    return { ok: false, reason: '空正文（JSON 语义比较要求非空 JSON 正文）' };
  }
  try {
    return { ok: true, value: JSON.parse(stripped) };
  } catch (e) {
    return { ok: false, reason: describeError(e) };
  }
}
```

