diffPlannedJson:

```ts
function diffPlannedJson(jsonCompare: {plannedJson, ignore}, actualBody: Buffer): JsonBodyDifference[] {
  const text = decodeUtf8Strict(actualBody);
  if (text === undefined) {
    return [{ pointer: '', message: '实际响应正文不是合法 UTF-8，无法按 JSON 语义比较' }];
  }
  const parsed = parseJsonBodyText(text);
  if (!parsed.ok) {
    return [{ pointer: '', message: `实际响应正文不是合法 JSON：${parsed.reason}` }];
  }
  const out: JsonBodyDifference[] = [];
  diffJsonValues(jsonCompare.plannedJson, parsed.value, '', jsonCompare.ignore, out);
  return out;
}
```

